import java.util.*;import java.util.zip.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;
public class VerifyNativeReaderUiHooks{
 static Map<String,ClassDef> load(String path)throws Exception{Map<String,ClassDef> map=new HashMap<>();try(var z=new ZipFile(path)){for(var e:Collections.list(z.entries()))if(e.getName().matches("classes[0-9]*\\.dex"))try(var in=new java.io.BufferedInputStream(z.getInputStream(e))){for(var c:DexBackedDexFile.fromInputStream(Opcodes.getDefault(),in).getClasses())map.put(c.getType(),c);}}return map;}
 static String key(Method m){return m.getName()+m.getParameterTypes()+m.getReturnType();}
 static String ref(Instruction i){return i instanceof ReferenceInstruction r?r.getReference().toString():"";}
 static String signature(Instruction i){String s=i.getOpcode().name()+" "+ref(i);if(i instanceof OneRegisterInstruction r)s+=" A"+r.getRegisterA();if(i instanceof TwoRegisterInstruction r)s+=" B"+r.getRegisterB();if(i instanceof ThreeRegisterInstruction r)s+=" C"+r.getRegisterC();if(i instanceof FiveRegisterInstruction r)s+=" args"+r.getRegisterCount()+":"+r.getRegisterC()+","+r.getRegisterD()+","+r.getRegisterE()+","+r.getRegisterF()+","+r.getRegisterG();if(i instanceof RegisterRangeInstruction r)s+=" range"+r.getStartRegister()+":"+r.getRegisterCount();if(i instanceof WideLiteralInstruction r)s+=" lit"+r.getWideLiteral();return s;}
 static int addressIndex(List<Instruction> a,int address){int at=0;for(int i=0;i<a.size();i++){if(at==address)return i;at+=a.get(i).getCodeUnits();}throw new AssertionError("target missing "+address);}
 static List<String> normalize(Method m,Set<Integer> skip){List<Instruction> all=new ArrayList<>();m.getImplementation().getInstructions().forEach(all::add);int[] projection=new int[all.size()+1];int n=0;for(int i=0;i<all.size();i++){projection[i]=n;if(!skip.contains(i))n++;}projection[all.size()]=n;List<String> result=new ArrayList<>();int address=0;for(int i=0;i<all.size();i++){Instruction ins=all.get(i);if(!skip.contains(i)){String value=signature(ins);if(ins instanceof OffsetInstruction o)value+=" target"+projection[addressIndex(all,address+o.getCodeOffset())];result.add(value);}address+=ins.getCodeUnits();}return result;}
 public static void main(String[] a)throws Exception{Map<String,ClassDef> before=load(a[0]),after=load(a[1]);int methods=0,sites=0;
 for(var c:after.values())for(var m:c.getMethods()){if(!c.getType().startsWith("Lo/")&&!c.getType().startsWith("Ljp/syoboi/"))continue;if(m.getImplementation()==null)continue;List<Instruction> code=new ArrayList<>();m.getImplementation().getInstructions().forEach(code::add);Set<Integer> skip=new HashSet<>();for(int i=0;i<code.size();i++){String r=ref(code.get(i));if(r.startsWith("Lapp/morphe/extension/chmate/NativeSubjectCache;->result")){if(code.get(i-2).getOpcode()!=Opcode.CHECK_CAST||code.get(i-1).getOpcode()!=Opcode.IGET||code.get(i+1).getOpcode()!=Opcode.MOVE_RESULT_OBJECT||code.get(i+2).getOpcode()!=Opcode.CHECK_CAST)throw new AssertionError("cache sequence");for(int j=i-2;j<=i+2;j++)skip.add(j);sites++;}
 else if(r.startsWith("Lapp/morphe/extension/chmate/PostingMenuPlacement;->prepare")||r.startsWith("Lapp/morphe/extension/chmate/PatrolErrorDetails;->")){skip.add(i);if(r.contains("->append")){if(code.get(i+1).getOpcode()!=Opcode.MOVE_RESULT_OBJECT)throw new AssertionError("append result");skip.add(i+1);}sites++;}}
 if(skip.isEmpty())continue;ClassDef old=before.get(c.getType());if(old==null)throw new AssertionError("native owner missing");Method original=null;for(var om:old.getMethods())if(key(om).equals(key(m)))original=om;if(original==null||original.getImplementation().getRegisterCount()!=m.getImplementation().getRegisterCount())throw new AssertionError("register contract "+m);if(!normalize(original,Collections.emptySet()).equals(normalize(m,skip)))throw new AssertionError("native instructions/arguments/targets changed "+m);methods++;
 }
 int expected=a[2].equals("191")?1:a[2].equals("226")?2:4;if(methods!=expected)throw new AssertionError("method count "+methods+" != "+expected);System.out.println("PASS "+a[2]+" native reader/UI hooks: "+methods+" methods, "+sites+" insertions; original instructions/registers/branch targets retained");
 }
}
